def skill():
    lose = factorial(4)
    win = 4 * factorial(4) // (1 * 1 * 2) + 2 * factorial(4) // (1 * 6)
    v = Fraction(win, win + lose)
    return v.numerator + v.denominator

def standard():
    from itertools import product
    tot = fav = 0
    for seq in product(range(6), repeat=4):
        c = [1]*4 + [0]*2
        for i in seq:
            c[i] ^= 1
        if len(set(c)) == 1:
            tot += 1
            fav += c[0] == 1
    v = Fraction(fav, tot)
    return v.numerator + v.denominator

def unique():
    return [standard()]
